import { imageUrl, imageSrcSet, responsiveWidths, videoUrl } from "./urls.js";

/**
 * Binds the URL helpers to an asset map (see asset-map.json, generated by
 * scripts/cloudinary/generate-asset-map.mjs) and adds lookup by stable key or by original local path.
 *
 * Unknown keys/paths are never silently ignored and there is NO local-file fallback:
 *   - strict (the default, in development AND production): throws, so a typo is caught immediately and, via
 *     scripts/cloudinary/check-asset-references.mjs, before it can ship;
 *   - non-strict (tests only): reports via `report` and returns `null`.
 *
 * Kept free of JSON/Vite imports so it can be unit-tested directly in Node.
 */
export function createAssetResolver(map, { strict = true, report = (msg) => console.error(msg) } = {}) {
  const miss = (what) => {
    const msg = `[cloudinary] ${what}`;
    if (strict) throw new Error(msg);
    report(msg);
    return null;
  };

  /** Normalise "/journey/x.jpg", "./public/journey/x.jpg", "public\\journey\\x.jpg" -> "public/journey/x.jpg". */
  const normalisePath = (p) => {
    let s = String(p ?? "").replace(/\\/g, "/").replace(/[?#].*$/, "").replace(/^\.\//, "");
    if (s.startsWith("/")) s = "public" + s; // web path of a file under public/
    return s;
  };

  const hasAsset = (key) => Object.prototype.hasOwnProperty.call(map.assets, key);
  const getAsset = (key) => (hasAsset(key) ? map.assets[key] : miss(`unknown asset key "${key}"`));
  const assetKeyFromPath = (p) => {
    const norm = normalisePath(p);
    return Object.prototype.hasOwnProperty.call(map.paths, norm) ? map.paths[norm] : miss(`no asset mapped for local path "${p}"`);
  };
  const getAssetByPath = (p) => {
    const key = assetKeyFromPath(p);
    return key ? map.assets[key] : null;
  };

  // Each of these returns null when the key is unknown (non-strict) so callers can fall back.
  const withAsset = (key, fn) => {
    const asset = getAsset(key);
    return asset ? fn(asset) : null;
  };

  /**
   * `src` + `srcSet` + `sizes` for an <img>, ready to spread: <img {...getImageProps(key, { widths, sizes })} alt="" />
   *   widths   - candidate widths (see WIDTH_LADDERS); capped at the asset's native width, never upscaled
   *   sizes    - the `sizes` attribute, or a function (aspectRatio, asset) => string. Required: a srcset without an
   *              accurate `sizes` makes the browser assume 100vw. Build it with coverSize()/buildSizes().
   *   srcWidth - width of the plain `src` (only used by browsers without srcset). Default: largest candidate <= 1200.
   * Other options (quality, format, allowLossy) are forwarded to the URL helpers.
   */
  const getImageProps = (key, { widths, sizes, srcWidth, ...imageOpts } = {}) =>
    withAsset(key, (a) => {
      if (!Array.isArray(widths) || !widths.length) throw new Error(`[cloudinary] getImageProps("${key}") needs a widths array`);
      const sizesValue = typeof sizes === "function" ? sizes(a.width / a.height, a) : sizes;
      if (typeof sizesValue !== "string" || !sizesValue) throw new Error(`[cloudinary] getImageProps("${key}") needs an accurate sizes string`);
      const candidates = responsiveWidths(a, widths);
      const src = imageUrl(a, { ...imageOpts, width: srcWidth ?? ([...candidates].reverse().find((w) => w <= 1200) ?? candidates[0]) });
      return { src, srcSet: imageSrcSet(a, widths, imageOpts), sizes: sizesValue };
    });

  return {
    hasAsset,
    getAsset,
    getAssetByPath,
    assetKeyFromPath,
    /** The exact, untransformed delivery URL recorded at upload time. */
    getAssetUrl: (key) => withAsset(key, (a) => a.url),
    getImageUrl: (key, opts) => withAsset(key, (a) => imageUrl(a, opts)),
    getImageSrcSet: (key, widths, opts) => withAsset(key, (a) => imageSrcSet(a, widths, opts)),
    getImageProps,
    getVideoUrl: (key, opts) => withAsset(key, (a) => videoUrl(a, opts)),
  };
}
